# concepts:
# pixel erosion, droplet nucleation, gravity-driven translation, static background retention, mass conservation
# description:
# Input: a centered pink scoop atop a maroon cone on grey ground, with some teal droplets below.
# Output: simulate one melt step: erode the scoop's lower layer, spawn equal teal droplets beneath, let existing droplets fall one cell, keep cone, highlights, and ground intact.

from common import *
import numpy as np
import random

def main(input_grid):
    bg=Color.GREY; scoop=Color.PINK; drop=Color.TEAL
    out=input_grid.copy()
    h,w=out.shape
    erode=[]
    for i,j in zip(*np.where(input_grid==scoop)):
        for dj in (-1,0,1):
            ni,nj=i+1,j+dj
            if ni<0 or ni>=h or nj<0 or nj>=w or input_grid[ni,nj]!=scoop:
                erode.append((i,j)); break
    for i,j in erode: out[i,j]=bg
    for i,j in erode:
        if i+1<h and out[i+1,j]==bg: out[i+1,j]=drop
    for i,j in zip(*np.where(input_grid==drop)):
        if i+1<h and out[i+1,j]==bg:
            out[i,j]=bg; out[i+1,j]=drop
    return out

def generate_input():
    n=random.randint(15,30); m=random.randint(15,30)
    grid=np.full((n,m),Color.GREY)
    r=random.randint(3, max(3, min(n,m)//6))
    cy, cx = n//3, m//2
    for di in range(-r,1):
        for dj in range(-r, r+1):
            if di*di + dj*dj <= r*r:
                grid[cy+di, cx+dj]=Color.PINK
    grid[cy-r+1, cx - r//2] = Color.YELLOW
    for t in range(r+1):
        row=cy+t
        for dj in range(-r+t, r-t+1): grid[row, cx+dj]=Color.MAROON
    for _ in range(random.randint(3,6)):
        j=random.randint(cx-r+1, cx+r-1)
        i=cy+random.randint(1, r+1)
        if grid[i,j]==Color.GREY: grid[i,j]=Color.TEAL
    return grid
